const DAYS_IN_BILLING_CYCLE = 30;

export function calculateRefund(plan, daysUsed) {
  const planDetails = PLANS[plan];
  if (!planDetails) {
    throw new Error(`Invalid plan: ${plan}`);
  }

  const { price } = planDetails;
  const dailyRate = price / DAYS_IN_BILLING_CYCLE;
  const refund = price - (dailyRate * daysUsed);

  return Math.max(0, refund); // Ensure non-negative refund
}

